from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump = {a: b for a, b in jumps}

    def resolve(x: int) -> int:
        while x in jump:
            x = jump[x]
        return x

    def target(p: int, r: int) -> int:
        t = p + r
        if t > n:
            t = 2 * n - t
        return resolve(t)

    # trans[s] holds the landing cell for each roll 1..m from transient cell s
    trans = {s: [target(s, r) for r in range(1, m + 1)] for s in range(n)}

    # Transient cells reachable from the start (cell n is the terminal cell)
    reach = [0]
    seen = {0}
    i = 0
    while i < len(reach):
        s = reach[i]
        i += 1
        for t in trans[s]:
            if t < n and t not in seen:
                seen.add(t)
                reach.append(t)

    # If any reachable cell cannot reach n, the game may never end
    good = set()
    changed = True
    while changed:
        changed = False
        for s in reach:
            if s not in good and any(t == n or t in good for t in trans[s]):
                good.add(s)
                changed = True
    if any(s not in good for s in reach):
        return None

    # Solve (I - P) E = 1 over reachable transient cells, exactly
    idx = {s: i for i, s in enumerate(reach)}
    k = len(reach)
    A = [[Fraction(0)] * k for _ in range(k)]
    b = [Fraction(1)] * k
    step = Fraction(1, m)
    for i, s in enumerate(reach):
        A[i][i] += 1
        for t in trans[s]:
            if t < n:
                A[i][idx[t]] -= step

    for col in range(k):
        piv = next((r for r in range(col, k) if A[r][col] != 0), None)
        if piv is None:
            return None
        A[col], A[piv] = A[piv], A[col]
        b[col], b[piv] = b[piv], b[col]

        inv = 1 / A[col][col]
        A[col] = [x * inv for x in A[col]]
        b[col] *= inv

        for r in range(k):
            if r != col and A[r][col] != 0:
                f = A[r][col]
                A[r] = [x - f * y for x, y in zip(A[r], A[col])]
                b[r] -= f * b[col]

    # Cell 0 has index 0 in reach, and the matrix is now the identity
    ans = b[idx[0]]
    return [ans.numerator, ans.denominator]
